import React, { useState, useEffect, useRef } from 'react';
import { 
  Container, 
  Paper, 
  Typography, 
  Box, 
  Button,
  CircularProgress,
  Alert,
  Snackbar
} from '@mui/material';
import MicIcon from '@mui/icons-material/Mic';
import StopIcon from '@mui/icons-material/Stop';
import axios from 'axios';
import WaveSurfer from 'wavesurfer.js';

const API_BASE_URL = 'http://localhost:8000';

function App() {
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [messages, setMessages] = useState([]);
  const [error, setError] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isCaseStarted, setIsCaseStarted] = useState(false);
  const audioContextRef = useRef(null);
  const analyserRef = useRef(null);
  const canvasRef = useRef(null);
  const audioRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const chunksRef = useRef([]);

  useEffect(() => {
    // Initialize audio context and analyzer
    audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
    analyserRef.current = audioContextRef.current.createAnalyser();
    analyserRef.current.fftSize = 256;

    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
      if (audioRef.current) {
        audioRef.current.pause();
      }
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
      }
    };
  }, []);

  const getInitialQuestion = async () => {
    try {
      setIsProcessing(true);
      setError(null);
      const response = await axios.get(`${API_BASE_URL}/api/initial-question`);
      setMessages([{ role: 'ai', text: response.data.text }]);
      await playAudio(response.data.audio_url);
      setIsCaseStarted(true);
    } catch (error) {
      setError('Failed to get initial question. Please try again.');
      console.error('Error getting initial question:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      
      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
        ? 'audio/webm;codecs=opus'
        : 'audio/webm'; // fallback
      
      console.log('Using MIME type:', mimeType);
      
      const recorder = new MediaRecorder(stream, { mimeType });
      mediaRecorderRef.current = recorder;
      
      // Reset chunks array
      chunksRef.current = [];
      
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      recorder.onstop = async () => {
        try {
          const blob = new Blob(chunksRef.current, { type: recorder.mimeType });
          chunksRef.current = []; // clear for next recording
          
          console.log("🎤 Blob size:", blob.size);
          
          if (blob.size === 0) {
            setError("Recording failed. Please try again.");
            return;
          }
          
          const file = new File([blob], "recording.webm", { type: blob.type });
          const formData = new FormData();
          formData.append('file', file);
          
          await sendAudioToServer(formData);
        } catch (error) {
          console.error('Error processing recording:', error);
          setError('Failed to process recording. Please try again.');
        }
      };

      recorder.start();
      setIsRecording(true);
      startVisualization();
    } catch (error) {
      console.error('Error starting recording:', error);
      setError('Failed to start recording. Please check your microphone permissions.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      stopVisualization();
    }
  };

  const startVisualization = () => {
    const canvas = canvasRef.current;
    const canvasCtx = canvas.getContext('2d');
    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      if (!isRecording) return;

      requestAnimationFrame(draw);
      analyserRef.current.getByteFrequencyData(dataArray);

      canvasCtx.fillStyle = 'rgb(200, 200, 200)';
      canvasCtx.fillRect(0, 0, canvas.width, canvas.height);

      const barWidth = (canvas.width / bufferLength) * 2.5;
      let barHeight;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        barHeight = dataArray[i] / 2;

        canvasCtx.fillStyle = `rgb(50, ${barHeight + 100}, 50)`;
        canvasCtx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);

        x += barWidth + 1;
      }
    };

    draw();
  };

  const stopVisualization = () => {
    const canvas = canvasRef.current;
    const canvasCtx = canvas.getContext('2d');
    canvasCtx.clearRect(0, 0, canvas.width, canvas.height);
  };

  const sendAudioToServer = async (formData) => {
    setIsProcessing(true);
    try {
      const response = await axios.post(`${API_BASE_URL}/api/transcribe`, formData, {
        headers: { 
          'Content-Type': 'multipart/form-data',
        },
      });

      if (response.data) {
        setMessages((prev) => [
          ...prev,
          { role: 'user', text: response.data.transcript || 'User response transcribed...' },
          { role: 'ai', text: response.data.feedback || response.data.text },
        ]);

        await playAudio(response.data.audio_url);
      }
    } catch (error) {
      console.error('Error sending audio to server:', error);
      setError('Failed to process your response. Please try again.');
    } finally {
      setIsProcessing(false);
    }
  };

  const playAudio = async (audioUrl) => {
    try {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current = null;
      }

      const audio = new Audio(`${API_BASE_URL}${audioUrl}`);
      audioRef.current = audio;

      audio.onplay = () => setIsPlaying(true);
      audio.onended = () => {
        setIsPlaying(false);
        audioRef.current = null;
      };
      audio.onerror = (e) => {
        console.error('Audio playback error:', e);
        setError('Failed to play audio response. Please try again.');
        setIsPlaying(false);
        audioRef.current = null;
      };

      await audio.play();
    } catch (error) {
      console.error('Error playing audio:', error);
      setError('Failed to play audio response. Please try again.');
      setIsPlaying(false);
    }
  };

  const handleCloseError = () => {
    setError(null);
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      <Paper elevation={3} sx={{ p: 3 }}>
        <Typography variant="h4" gutterBottom>
          Case Interview AI
        </Typography>

        {!isCaseStarted ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', mb: 3 }}>
            <Button
              variant="contained"
              color="primary"
              onClick={getInitialQuestion}
              disabled={isProcessing}
            >
              Generate Case
              {isProcessing && <CircularProgress size={24} sx={{ ml: 1 }} />}
            </Button>
          </Box>
        ) : (
          <>
            <Box sx={{ height: 400, overflowY: 'auto', mb: 2, p: 2, bgcolor: '#f5f5f5' }}>
              {messages.map((message, index) => (
                <Box
                  key={index}
                  sx={{
                    mb: 2,
                    p: 2,
                    bgcolor: message.role === 'ai' ? '#e3f2fd' : '#f5f5f5',
                    borderRadius: 1,
                  }}
                >
                  <Typography variant="body1">{message.text}</Typography>
                </Box>
              ))}
            </Box>

            <Box sx={{ mb: 2 }}>
              <canvas
                ref={canvasRef}
                width={800}
                height={100}
                style={{ width: '100%', height: '100px', backgroundColor: '#f5f5f5' }}
              />
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2 }}>
              {!isRecording ? (
                <Button
                  variant="contained"
                  color="primary"
                  startIcon={<MicIcon />}
                  onClick={startRecording}
                  disabled={isProcessing || isPlaying}
                >
                  Start Recording
                </Button>
              ) : (
                <Button
                  variant="contained"
                  color="error"
                  startIcon={<StopIcon />}
                  onClick={stopRecording}
                >
                  Stop Recording
                </Button>
              )}
              {isProcessing && <CircularProgress size={24} />}
            </Box>
          </>
        )}
      </Paper>

      <Snackbar
        open={!!error}
        autoHideDuration={6000}
        onClose={handleCloseError}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseError} severity="error" sx={{ width: '100%' }}>
          {error}
        </Alert>
      </Snackbar>
    </Container>
  );
}

export default App; 